## Why This Is Asked

Assess ability to design runtime-extensible components, manage threading, and reason about cache behavior in large-scale systems.

## Key Concepts

- Runtime registries for strategy extension
- Thread-safe, lock-free reads with bounded memory
- Eviction and read-through refresh choreography

## Code Example

```typescript
interface EvictionPolicy<K, V> {
  onPut(key: K, value: V, currentSize: number): number;
  onGet(key: K, value: V): void;
}
interface RefreshStrategy<V> {
  refresh(value: V): Promise<V> | V;
}
class CacheRegistry {
  private map = new Map<string, () => EvictionPolicy<any, any>>();
  register<K,V>(name: string, factory: () => EvictionPolicy<K,V>) {
    this.map.set(name, factory);
  }
  create<K,V>(name: string): EvictionPolicy<K,V> | undefined {
    const f = this.map.get(name);
    return f ? f() : undefined;
  }
}
class Cache<K, V> {
  private store = new Map<K, V>();
  constructor(private policyName: string, private registry: CacheRegistry) {}
  put(key: K, value: V) {
    const policy = this.registry.create<K,V>(this.policyName);
    // simplified
    this.store.set(key, value);
    policy?.onPut(key, value, this.store.size);
  }
  get(key: K): V | undefined {
    return this.store.get(key);
  }
