## Code Example
```typescript
interface Policy<T> {
  onRead(key: string, value: T, context: any): T
  onWrite(key: string, value: T, context: any): T
}

class StrongPolicy<T> implements Policy<T> {
  onRead(k: string, v: T) { return v }
  onWrite(k: string, v: T) { return v }
}
class ReadYourWritesPolicy<T> implements Policy<T> {
  onRead(k: string, v: T) { /* ensure read reflects recent writes */ return v }
  onWrite(k: string, v: T) { return v }
}
class MonotonicPolicy<T> implements Policy<T> {
  onRead(k: string, v: T) { return v }
  onWrite(k: string, v: T) { return v }
}

class PolicyRegistry {
  static get<T>(name: string): Policy<T> {
    switch (name) {
      case 'Strong': return new StrongPolicy<T>()
      case 'ReadYourWrites': return new ReadYourWritesPolicy<T>()
      case 'Monotonic': return new MonotonicPolicy<T>()
      default: throw new Error('Unknown policy')
    }
  }
}

class CacheClient<T> {
  constructor(private policy: Policy<T>) {}
  get(key: string): T {
    const v = /* fetch from store */ (null as unknown as T)
    return this.policy.onRead(key, v, {})
  }
  put(key: string, value: T) {
    this.policy.onWrite(key, value, {})
    // store value
  }
}

const policy = PolicyRegistry.get<string>('ReadYourWrites')
const cache = new CacheClient<string>(policy)
```

